#include <stdio.h>

struct Student {
    int roll;
    char name[20];
    float marks;
};

int main(void) {
    struct Student s[3] = {
        {1, "Ravi", 72.5f},
        {2, "Anjali", 88.0f},
        {3, "Xecxec", 95.5f}
    };

    FILE *fp = fopen("students.dat", "wb");
    if (fp == NULL) {
        perror("students.dat");
        return 1;
    }

    size_t written = fwrite(s, sizeof(struct Student), 3, fp);
    fclose(fp);

    printf("Wrote %zu records\n", written);
    printf("Each record is %zu bytes\n", sizeof(struct Student));
    return 0;
}

#include <stdio.h>

struct Student {
    int roll;
    char name[20];
    float marks;
};

int main(void) {
    FILE *fp = fopen("students.dat", "rb");
    if (fp == NULL) {
        perror("students.dat");
        return 1;
    }

    struct Student st;

    while (fread(&st, sizeof st, 1, fp) == 1) {
        printf("%d  %-8s %.1f\n", st.roll, st.name, st.marks);
    }

    /* Jump straight to record 2 (index 1) */
    fseek(fp, 1 * (long)sizeof st, SEEK_SET);
    fread(&st, sizeof st, 1, fp);
    printf("Record 2 is %s\n", st.name);

    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    printf("File size: %ld bytes, %ld records\n", size, size / (long)sizeof st);

    fclose(fp);
    return 0;
}

#include <stdio.h>

struct Student {
    int roll;
    char name[20];
    float marks;
};

int main(void) {
    FILE *fp = fopen("students.dat", "r+b");
    if (fp == NULL) {
        perror("students.dat");
        return 1;
    }

    struct Student st;
    long pos = 2 * (long)sizeof st;

    fseek(fp, pos, SEEK_SET);
    fread(&st, sizeof st, 1, fp);
    st.marks = 99.0f;

    fseek(fp, pos, SEEK_SET);
    fwrite(&st, sizeof st, 1, fp);
    fclose(fp);

    printf("Updated %s to %.1f\n", st.name, st.marks);
    return 0;
}
